func ptrDetentionNotice(p unsafe.Pointer, c int32) any {
	r := (*detentionnotice.DetentionNotice)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DetentionOccurrenceID))
	case 4:
		return &r.ThreadKey
	case 5:
		return (*string)(unsafe.Pointer(&r.Kind))
	case 6:
		return (*string)(unsafe.Pointer(&r.Channel))
	case 7:
		return (*string)(unsafe.Pointer(&r.DeliveryStatus))
	case 8:
		return &r.Recipients
	case 9:
		return &r.Subject
	case 10:
		return &r.Body
	case 11:
		return &r.BodyHTML
	case 12:
		return (**string)(unsafe.Pointer(&r.TemplateVersionID))
	case 13:
		return (**string)(unsafe.Pointer(&r.PDFDocumentID))
	case 14:
		return &r.ScheduledFor
	case 15:
		return &r.SentAt
	case 16:
		return &r.DeliveredAt
	case 17:
		return &r.OpenedAt
	case 18:
		return &r.FailedAt
	case 19:
		return &r.FailureReason
	case 20:
		return &r.ProviderMessageID
	case 21:
		return (**string)(unsafe.Pointer(&r.SentByID))
	case 22:
		return &r.WasAutomatic
	case 23:
		return &r.SatisfiesRequirement
	case 24:
		return &r.QuotedFreeMinutes
	case 25:
		return &r.QuotedRate
	case 26:
		return &r.QuotedAmount
	case 27:
		return &r.Version
	case 28:
		return &r.CreatedAt
	case 29:
		return &r.UpdatedAt
	}
	return nil
}

func valueDetentionNotice(p unsafe.Pointer, c int32) any {
	r := (*detentionnotice.DetentionNotice)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.DetentionOccurrenceID)
	case 4:
		return r.ThreadKey
	case 5:
		return string(r.Kind)
	case 6:
		return string(r.Channel)
	case 7:
		return string(r.DeliveryStatus)
	case 8:
		if r.Recipients == nil {
			return nil
		}
		return r.Recipients
	case 9:
		return r.Subject
	case 10:
		return r.Body
	case 11:
		if r.BodyHTML == "" {
			return nil
		}
		return r.BodyHTML
	case 12:
		if r.TemplateVersionID == nil {
			return nil
		}
		return string(*r.TemplateVersionID)
	case 13:
		if r.PDFDocumentID == nil {
			return nil
		}
		return string(*r.PDFDocumentID)
	case 14:
		return r.ScheduledFor
	case 15:
		if r.SentAt == nil {
			return nil
		}
		return *r.SentAt
	case 16:
		if r.DeliveredAt == nil {
			return nil
		}
		return *r.DeliveredAt
	case 17:
		if r.OpenedAt == nil {
			return nil
		}
		return *r.OpenedAt
	case 18:
		if r.FailedAt == nil {
			return nil
		}
		return *r.FailedAt
	case 19:
		if r.FailureReason == "" {
			return nil
		}
		return r.FailureReason
	case 20:
		if r.ProviderMessageID == "" {
			return nil
		}
		return r.ProviderMessageID
	case 21:
		if r.SentByID == nil {
			return nil
		}
		return string(*r.SentByID)
	case 22:
		return r.WasAutomatic
	case 23:
		return r.SatisfiesRequirement
	case 24:
		return r.QuotedFreeMinutes
	case 25:
		return r.QuotedRate
	case 26:
		return r.QuotedAmount
	case 27:
		return r.Version
	case 28:
		return r.CreatedAt
	case 29:
		return r.UpdatedAt
	}
	return nil
}

